export function lookupPostalTransitNode(pincode: string): PostalTransitNode | undefined {
  const p = pincode.trim();
  return Object.values(INDIAN_PINCODES_REGISTRY).find(node => node.pincode === p);
}

export function getPostalNodesByDistrict(districtName: string): PostalTransitNode[] {
  const target = districtName.toLowerCase().trim();
  return Object.values(INDIAN_PINCODES_REGISTRY).filter(node => node.district.toLowerCase() === target);
}

export function getPostalNodesByState(stateCode: string): PostalTransitNode[] {
  const target = stateCode.toUpperCase().trim();
  return Object.values(INDIAN_PINCODES_REGISTRY).filter(node => node.stateCode === target);
}
